const { execSync } = require('child_process');
const fs = require('fs');
const ALERTAS = 'C:\\Users\\usuario\\Desktop\\Projeto-professor-William\\auditoria\\alertas-automaticos.md';
const CLAUDE = 'C:\\Users\\usuario\\AppData\\Roaming\\npm\\claude.cmd';

const prompt = 'Leia C:\\Users\\usuario\\Desktop\\Projeto-professor-William\\auditoria\\problemas.md e C:\\Users\\usuario\\Desktop\\Projeto-professor-William\\auditoria\\alertas-automaticos.md. Em ate 3 frases, diga o que mais precisa da atencao do Diretor agora, com base no que esta realmente escrito nesses arquivos, nunca invente. Responda em portugues direto, sem markdown, sem introducao.';

const cmd = '"' + CLAUDE + '" -p "' + prompt + '" --dangerously-skip-permissions --output-format text';

let resposta;
try {
  resposta = execSync(cmd, { encoding: 'utf8', timeout: 120000, maxBuffer: 10 * 1024 * 1024 }).trim();
} catch (e) {
  resposta = '(erro chamando o claude: ' + (e.message || String(e)) + ')';
}

const agora = new Date();
const pad = n => String(n).padStart(2, '0');
const dataStr = `${agora.getUTCFullYear()}-${pad(agora.getUTCMonth()+1)}-${pad(agora.getUTCDate())}`;
const horaStr = `${pad(agora.getUTCHours())}:${pad(agora.getUTCMinutes())}`;
const bloco = `\n## ${dataStr} ${horaStr} — n8n + Claude (sob demanda, julgamento real, sem custo novo)\n\n${resposta}\n`;

if (!fs.existsSync(ALERTAS)) {
  fs.writeFileSync(ALERTAS, '# Alertas automáticos — n8n\n\n' + bloco, 'utf8');
} else {
  fs.appendFileSync(ALERTAS, bloco, 'utf8');
}

return [{ json: { resposta } }];
